/* @lc app=leetcode id=2461 lang=kotlin */ class Solution { fun maximumSubarraySum(nums: IntArray, k: Int): Long = HashMap<Int, Int>().let { m -> nums.indices.fold(0L to 0L) { (s, best), i -> (s + nums[i]).let { s1 -> m.merge(nums[i], 1) { a, b -> a + b }.let { (if (i >= k) nums[i - k].let { out -> m.merge(out, -1) { a, b -> a + b }.also { if (it == 0) m.remove(out) }.let { s1 - out } } else s1).let { s2 -> s2 to (if (i >= k - 1 && m.size == k) maxOf(best, s2) else best) } } } }.second } }